import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    rows = data[2:2 + r]
    dist = [-1] * (r * c)
    q = deque()
    for i in range(r):
        row = rows[i]
        for j in range(c):
            if row[j] == 'B':
                dist[i * c + j] = 0
                q.append(i * c + j)
    if not q:
        print(-1)
        return
    best = 0
    while q:
        u = q.popleft()
        i, j = divmod(u, c)
        d = dist[u] + 1
        if i > 0 and dist[u - c] < 0:
            dist[u - c] = d; q.append(u - c)
        if i < r - 1 and dist[u + c] < 0:
            dist[u + c] = d; q.append(u + c)
        if j > 0 and dist[u - 1] < 0:
            dist[u - 1] = d; q.append(u - 1)
        if j < c - 1 and dist[u + 1] < 0:
            dist[u + 1] = d; q.append(u + 1)
        best = dist[u]
    print(best)

